(function() {
    'use strict';

    class EcoSystemArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'EcoSystem Architect: Platform Governance and Coopetition';
            this.version = '1.1.0';

            // Fully parallel en/es content for every round: title, description, event,
            // and the four decisions (label + A/B/C option text). Scoring reads only the
            // numeric select values (1/2/3), so localization never affects the model.
            this.ROUNDS = [
                {
                    eventThreshold: 1.8,
                    en: {
                        title: 'Round 1: Governance Charter Design',
                        description: 'UrbanGrid is a $450M smart city platform headquartered in Santiago, Chile, connecting 85 municipal partners and 340 complementors across Latin America and Europe. You serve as CEO facing a critical strategic inflection point.<br><br>Design the foundational governance charter. Your choices on data access, API standards, revenue sharing, and dispute resolution will determine whether UrbanGrid operates as an open ecosystem or a closed garden.',
                        event: 'A leading European city inquires about data access for sustainability initiatives. A complementor requests the same data. Your data policy is tested: restrictive policies force a difficult choice between disappointing the city or breaking stated policy. Open policies generate goodwill and trust.',
                        decisions: [
                            { label: 'Data Access Policy', optA: 'Restrictive: aggregated data only; retain detailed data for proprietary services', optB: 'Tiered: graduated access by complementor tier; anonymized municipal data', optC: 'Open: full non-personalized municipal data for all complementors; equal access' },
                            { label: 'API Standardization', optA: 'Proprietary APIs, discretionary access, no transparency on roadmap', optB: 'Standard APIs with documented SLA, quarterly roadmap transparency', optC: 'Open API standards, full feature parity, complementor input on development' },
                            { label: 'Revenue Share Model', optA: 'Extractive: 40-50% share, opaque pricing, platform services exempt', optB: 'Transparent: 25-35% share, published schedule, same terms for all', optC: 'Fair: 15-25% share, volume discounts, platform follows same rules' },
                            { label: 'Dispute Resolution', optA: 'No formal structure; disputes handled internally by management', optB: 'Advisory board with non-binding recommendations and grievance process', optC: 'Independent board with binding arbitration and external legal review' }
                        ]
                    },
                    es: {
                        title: 'Ronda 1: Diseño del Estatuto de Gobernanza',
                        description: 'UrbanGrid es una plataforma de ciudad inteligente de $450M con sede en Santiago de Chile, que conecta a 85 socios municipales y 340 complementadores en América Latina y Europa. Eres CEO ante un punto de inflexión estratégico crítico.<br><br>Diseña el estatuto de gobernanza fundacional. Tus decisiones sobre acceso a datos, estándares de API, reparto de ingresos y resolución de disputas determinarán si UrbanGrid opera como un ecosistema abierto o un jardín cerrado.',
                        event: 'Una ciudad europea líder consulta sobre acceso a datos para iniciativas de sostenibilidad. Un complementador solicita los mismos datos. Tu política de datos se pone a prueba: las políticas restrictivas fuerzan una decisión difícil entre decepcionar a la ciudad o romper la política establecida. Las políticas abiertas generan buena voluntad y confianza.',
                        decisions: [
                            { label: 'Política de Acceso a Datos', optA: 'Restrictiva: solo datos agregados; retener datos detallados para servicios propios', optB: 'Escalonada: acceso graduado por nivel de complementador; datos municipales anonimizados', optC: 'Abierta: datos municipales no personalizados completos para todos; acceso igualitario' },
                            { label: 'Estandarización de API', optA: 'APIs propietarias, acceso discrecional, sin transparencia de hoja de ruta', optB: 'APIs estándar con SLA documentado, hoja de ruta trimestral transparente', optC: 'Estándares de API abiertos, paridad total de funciones, aportes de complementadores' },
                            { label: 'Modelo de Reparto de Ingresos', optA: 'Extractivo: 40-50% de comisión, precios opacos, servicios de plataforma exentos', optB: 'Transparente: 25-35% de comisión, tarifario publicado, mismos términos para todos', optC: 'Justo: 15-25% de comisión, descuentos por volumen, la plataforma sigue las mismas reglas' },
                            { label: 'Resolución de Disputas', optA: 'Sin estructura formal; disputas gestionadas internamente por la dirección', optB: 'Consejo asesor con recomendaciones no vinculantes y proceso de quejas', optC: 'Consejo independiente con arbitraje vinculante y revisión legal externa' }
                        ]
                    }
                },
                {
                    eventThreshold: 1.8,
                    en: {
                        title: 'Round 2: Complementor Engagement and Coopetition',
                        description: 'UrbanGrid is considering launching its own mobility optimization service, directly competing with Citymobil, a key complementor startup. Meanwhile, complementors are watching your governance decisions closely.<br><br>Navigate the tension between cooperation and competition. Your choices affect whether complementors invest in the ecosystem or begin to defect.',
                        event: 'A leading mobility complementor receives an acquisition offer from a global competitor (Uber) and considers leaving the ecosystem. If governance has been exploitative, defection becomes likely and signals ecosystem untrustworthiness to all partners.',
                        decisions: [
                            { label: 'Competing Services Strategy', optA: 'Launch UrbanGrid Mobility using proprietary data advantage over complementors', optB: 'Launch services under same governance terms as complementors, compete fairly', optC: 'Partner with leading complementor to co-develop next-gen services together' },
                            { label: 'Conflict Management', optA: 'Deny allegations of unfair treatment; maintain full control', optB: 'Investigate allegations; implement corrective measures if substantiated', optC: 'Proactive fairness: publish ranking criteria, run quarterly audits' },
                            { label: 'Ecosystem Investment', optA: 'Minimal: standard documentation only, limited developer support', optB: 'Moderate: developer program, integration engineers, annual hackathon ($500K)', optC: 'Aggressive: full support, $2M grant fund, shared research partnerships' },
                            { label: 'Complementor Revenue Protection', optA: 'Extract value from complementor businesses through competing services', optB: 'Honor existing contracts; avoid directly harming complementor revenue', optC: 'Revenue sharing models ensuring complementors benefit even when competing' }
                        ]
                    },
                    es: {
                        title: 'Ronda 2: Compromiso con Complementadores y Coopetencia',
                        description: 'UrbanGrid evalúa lanzar su propio servicio de optimización de movilidad, compitiendo directamente con Citymobil, una startup complementadora clave. Mientras tanto, los complementadores observan de cerca tus decisiones de gobernanza.<br><br>Navega la tensión entre cooperación y competencia. Tus decisiones determinan si los complementadores invierten en el ecosistema o comienzan a desertar.',
                        event: 'Un complementador líder de movilidad recibe una oferta de adquisición de un competidor global (Uber) y considera abandonar el ecosistema. Si la gobernanza ha sido explotadora, la deserción se vuelve probable y señala falta de confianza en el ecosistema para todos los socios.',
                        decisions: [
                            { label: 'Estrategia de Servicios en Competencia', optA: 'Lanzar UrbanGrid Mobility usando la ventaja de datos propios sobre complementadores', optB: 'Lanzar servicios bajo los mismos términos de gobernanza que los complementadores, competir con equidad', optC: 'Asociarse con un complementador líder para co-desarrollar servicios de próxima generación' },
                            { label: 'Gestión de Conflictos', optA: 'Negar las acusaciones de trato injusto; mantener el control total', optB: 'Investigar las acusaciones; implementar medidas correctivas si se comprueban', optC: 'Equidad proactiva: publicar criterios de ranking, realizar auditorías trimestrales' },
                            { label: 'Inversión en el Ecosistema', optA: 'Mínima: solo documentación estándar, soporte limitado a desarrolladores', optB: 'Moderada: programa de desarrolladores, ingenieros de integración, hackathon anual ($500K)', optC: 'Agresiva: soporte total, fondo de subvenciones de $2M, alianzas de investigación compartidas' },
                            { label: 'Protección de Ingresos del Complementador', optA: 'Extraer valor de los negocios de los complementadores mediante servicios en competencia', optB: 'Honrar los contratos existentes; evitar dañar directamente los ingresos del complementador', optC: 'Modelos de reparto de ingresos que benefician al complementador incluso al competir' }
                        ]
                    }
                },
                {
                    eventThreshold: 1.8,
                    en: {
                        title: 'Round 3: EU Regulatory Pressure',
                        description: 'EU authorities are evaluating whether UrbanGrid qualifies as a gatekeeper under the Digital Markets Act. Compliance with DMA requirements (data interoperability, API fairness, algorithm transparency, self-preferencing prohibition) could become mandatory.<br><br>Decide how to position UrbanGrid relative to emerging regulation. Resistance risks fines and market exclusion; leadership creates competitive advantage.',
                        event: 'EU authorities formally designate UrbanGrid as a gatekeeper. DMA compliance becomes mandatory immediately. Teams that proactively aligned transition smoothly. Those that resisted face emergency compliance costs ($15-25M) and potential fines for prior non-compliance.',
                        decisions: [
                            { label: 'DMA Compliance Approach', optA: 'Resist: argue not a gatekeeper, prepare litigation strategy', optB: 'Negotiate: begin voluntary alignment, position as responsible platform', optC: 'Lead: proactively embrace DMA principles, invite industry-wide adoption' },
                            { label: 'Data Sharing Roadmap', optA: 'Continue restrictive policies; data is a proprietary asset to protect', optB: 'Modest sharing with tier 1 complementors; gradual compliance roadmap', optC: 'Aggressive: full access for all complementors by Year 2, transparent roadmap' },
                            { label: 'Algorithmic Transparency', optA: 'Hide algorithm details; claim proprietary trade secret protection', optB: 'High-level description of ranking criteria; no detailed model disclosure', optC: 'Full specification published, third-party fairness audit, open-source components' },
                            { label: 'Regulatory Engagement Posture', optA: 'Adversarial: contest inquiries, allocate litigation budget', optB: 'Cooperative: engage with regulators, implement corrections when needed', optC: 'Leadership: propose industry standards, become a thought leader in governance' }
                        ]
                    },
                    es: {
                        title: 'Ronda 3: Presión Regulatoria de la UE',
                        description: 'Las autoridades de la UE evalúan si UrbanGrid califica como guardián de acceso (gatekeeper) bajo la Ley de Mercados Digitales (DMA). El cumplimiento de los requisitos de la DMA (interoperabilidad de datos, equidad de API, transparencia de algoritmos, prohibición de autopreferencia) podría volverse obligatorio.<br><br>Decide cómo posicionar a UrbanGrid frente a la regulación emergente. La resistencia arriesga multas y exclusión del mercado; el liderazgo crea ventaja competitiva.',
                        event: 'Las autoridades de la UE designan formalmente a UrbanGrid como guardián de acceso. El cumplimiento de la DMA se vuelve obligatorio de inmediato. Los equipos que se alinearon proactivamente hacen una transición fluida. Quienes resistieron enfrentan costos de cumplimiento de emergencia ($15-25M) y posibles multas por incumplimiento previo.',
                        decisions: [
                            { label: 'Enfoque de Cumplimiento de la DMA', optA: 'Resistir: argumentar que no es guardián de acceso, preparar estrategia de litigio', optB: 'Negociar: iniciar alineación voluntaria, posicionarse como plataforma responsable', optC: 'Liderar: adoptar proactivamente los principios de la DMA, invitar a su adopción sectorial' },
                            { label: 'Hoja de Ruta de Compartición de Datos', optA: 'Continuar con políticas restrictivas; los datos son un activo propio a proteger', optB: 'Compartición modesta con complementadores de nivel 1; hoja de ruta gradual', optC: 'Agresiva: acceso total para todos los complementadores al Año 2, hoja de ruta transparente' },
                            { label: 'Transparencia Algorítmica', optA: 'Ocultar detalles del algoritmo; alegar protección de secreto comercial', optB: 'Descripción general de los criterios de ranking; sin divulgar el modelo detallado', optC: 'Especificación completa publicada, auditoría de equidad por terceros, componentes de código abierto' },
                            { label: 'Postura de Relación con Reguladores', optA: 'Adversarial: impugnar las consultas, asignar presupuesto de litigio', optB: 'Cooperativa: colaborar con los reguladores, implementar correcciones cuando se requieran', optC: 'Liderazgo: proponer estándares sectoriales, ser referente en gobernanza' }
                        ]
                    }
                },
                {
                    eventThreshold: 1.8,
                    en: {
                        title: 'Round 4: Ecosystem Crisis and Stakeholder Alignment',
                        description: 'Crisis: leading complementors are launching an alternative open platform as an UrbanGrid competitor. Several key partners consider defection. Municipalities demand greater transparency. Investors question governance strategy.<br><br>Respond to the crisis and decide how to strengthen — or lose — your stakeholder coalitions.',
                        event: 'Leading complementors launch an alternative open-source platform. Teams with fair governance see minimal defection (5-10% of complementors). Teams with exploitative governance face significant exodus (25-40% of complementors leave).',
                        decisions: [
                            { label: 'Response to Complementor Complaints', optA: 'Minimize and deny concerns; adopt defensive legal posture', optB: 'Publicly acknowledge concerns; commit to specific improvements with timeline', optC: 'Invite complementors to co-design a governance transformation initiative' },
                            { label: 'Municipal Relationship Management', optA: 'Maintain terms unchanged; argue current value delivery is sufficient', optB: 'Offer data access improvements; consult municipalities on governance evolution', optC: 'Empower municipalities with governance representation and oversight authority' },
                            { label: 'Competitive Positioning vs Ecosystem Health', optA: 'Maximize UrbanGrid competitive position; accept complementor defection', optB: 'Balance competitiveness with ecosystem vitality and partner retention', optC: 'Prioritize ecosystem health; restrict platform competing services' },
                            { label: 'Investor Communication Strategy', optA: 'Emphasize short-term revenue and margin defense to reassure investors', optB: 'Reframe open governance as long-term risk mitigation strategy', optC: 'Growth narrative: open ecosystem creates larger total addressable market' }
                        ]
                    },
                    es: {
                        title: 'Ronda 4: Crisis del Ecosistema y Alineamiento de Grupos de Interés',
                        description: 'Crisis: complementadores líderes están lanzando una plataforma abierta alternativa como competidora de UrbanGrid. Varios socios clave consideran desertar. Los municipios exigen mayor transparencia. Los inversionistas cuestionan la estrategia de gobernanza.<br><br>Responde a la crisis y decide cómo fortalecer — o perder — tus coaliciones de grupos de interés.',
                        event: 'Complementadores líderes lanzan una plataforma alternativa de código abierto. Los equipos con gobernanza justa ven una deserción mínima (5-10% de los complementadores). Los equipos con gobernanza explotadora enfrentan un éxodo significativo (25-40% se van).',
                        decisions: [
                            { label: 'Respuesta a las Quejas de Complementadores', optA: 'Minimizar y negar las preocupaciones; adoptar una postura legal defensiva', optB: 'Reconocer públicamente las preocupaciones; comprometerse a mejoras concretas con plazos', optC: 'Invitar a los complementadores a co-diseñar una iniciativa de transformación de la gobernanza' },
                            { label: 'Gestión de Relaciones con Municipios', optA: 'Mantener los términos sin cambios; argumentar que el valor actual es suficiente', optB: 'Ofrecer mejoras de acceso a datos; consultar a los municipios sobre la evolución de la gobernanza', optC: 'Empoderar a los municipios con representación y autoridad de supervisión en la gobernanza' },
                            { label: 'Posición Competitiva vs. Salud del Ecosistema', optA: 'Maximizar la posición competitiva de UrbanGrid; aceptar la deserción de complementadores', optB: 'Equilibrar la competitividad con la vitalidad del ecosistema y la retención de socios', optC: 'Priorizar la salud del ecosistema; restringir los servicios en competencia de la plataforma' },
                            { label: 'Estrategia de Comunicación con Inversionistas', optA: 'Enfatizar los ingresos a corto plazo y la defensa de márgenes para tranquilizar a los inversionistas', optB: 'Replantear la gobernanza abierta como estrategia de mitigación de riesgos a largo plazo', optC: 'Narrativa de crecimiento: un ecosistema abierto crea un mercado direccionable mayor' }
                        ]
                    }
                },
                {
                    eventThreshold: 1.8,
                    en: {
                        title: 'Round 5: Long-Term Ecosystem Architecture',
                        description: 'Final round: institutionalize your governance commitments and design the long-term architecture for UrbanGrid. A global economic downturn tests the resilience of your ecosystem.<br><br>Your choices here determine whether UrbanGrid becomes a sustainable ecosystem enabler commanding premium valuation, or faces structural decline and ecosystem fragmentation.',
                        event: 'Global economic downturn hits. Complementor startups face funding crises. Platforms with fair governance and strong relationships weather the storm together. Platforms with exploitative governance see ecosystem collapse as underfunded partners exit.',
                        decisions: [
                            { label: 'Governance Permanence', optA: 'Flexible: policies changeable at UrbanGrid discretion anytime', optB: 'Codified: long-term contracts with stable governance board oversight', optC: 'Constitutional: binding charter with multi-stakeholder amendment process' },
                            { label: 'Stakeholder Representation', optA: 'No formal representation; occasional advisory with no authority', optB: 'Regular governance bodies with advisory capacity and annual reviews', optC: 'Binding multi-stakeholder governance with veto authority on major changes' },
                            { label: 'Data Ownership Model', optA: 'UrbanGrid owns all platform data; partners get licensed access only', optB: 'Tiered: municipalities own operational data; shared analytics layer', optC: 'Data Commons: shared stewardship with distributed access and revenue sharing' },
                            { label: 'Open-Source Commitment', optA: 'No open-source; proprietary platform with full lock-in strategy', optB: 'Limited: SDKs and libraries open-sourced; platform remains proprietary', optC: 'Significant: core APIs open-source, governance docs public, commons model' }
                        ]
                    },
                    es: {
                        title: 'Ronda 5: Arquitectura del Ecosistema a Largo Plazo',
                        description: 'Ronda final: institucionaliza tus compromisos de gobernanza y diseña la arquitectura de largo plazo para UrbanGrid. Una recesión económica global pone a prueba la resiliencia de tu ecosistema.<br><br>Tus decisiones aquí determinan si UrbanGrid se convierte en un habilitador de ecosistema sostenible con valoración premium, o enfrenta un declive estructural y la fragmentación del ecosistema.',
                        event: 'Golpea una recesión económica global. Las startups complementadoras enfrentan crisis de financiamiento. Las plataformas con gobernanza justa y relaciones sólidas capean el temporal juntas. Las plataformas con gobernanza explotadora ven colapsar su ecosistema cuando los socios sin fondos se retiran.',
                        decisions: [
                            { label: 'Permanencia de la Gobernanza', optA: 'Flexible: políticas modificables a discreción de UrbanGrid en cualquier momento', optB: 'Codificada: contratos de largo plazo con supervisión de un consejo de gobernanza estable', optC: 'Constitucional: estatuto vinculante con proceso de enmienda multi-actor' },
                            { label: 'Representación de Grupos de Interés', optA: 'Sin representación formal; asesoría ocasional sin autoridad', optB: 'Órganos de gobernanza regulares con capacidad consultiva y revisiones anuales', optC: 'Gobernanza multi-actor vinculante con autoridad de veto en cambios mayores' },
                            { label: 'Modelo de Propiedad de Datos', optA: 'UrbanGrid posee todos los datos de la plataforma; los socios solo obtienen acceso licenciado', optB: 'Escalonado: los municipios poseen los datos operativos; capa de analítica compartida', optC: 'Bien Común de Datos: administración compartida con acceso distribuido y reparto de ingresos' },
                            { label: 'Compromiso con el Código Abierto', optA: 'Sin código abierto; plataforma propietaria con estrategia de bloqueo total', optB: 'Limitado: SDKs y librerías de código abierto; la plataforma sigue siendo propietaria', optC: 'Significativo: APIs centrales de código abierto, documentos de gobernanza públicos, modelo de bien común' }
                        ]
                    }
                }
            ];
        }

        _lang() {
            var l = (window.mySimulation && window.mySimulation.language) ||
                    (document.documentElement && document.documentElement.lang) || 'en';
            return (l === 'es') ? 'es' : 'en';
        }

        _L(period) {
            var idx = Math.min((period || 1) - 1, this.ROUNDS.length - 1);
            var r = this.ROUNDS[idx];
            return r[this._lang()] || r.en;
        }

        _t(key, params) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                return window.mySimulation.t(key, params);
            }
            return key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 450,
                    ecosystemHealth: 55,
                    regulatoryCompliance: 50,
                    stakeholderAlignment: 50,
                    complementors: 340,
                    activeRate: 60,
                    activeComplementors: 204,
                    compositeScore: 0,
                    revenueHistory: [],
                    ecosystemHistory: [],
                    regulatoryHistory: [],
                    stakeholderHistory: [],
                    compositeHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { decision1: 2, decision2: 2, decision3: 2, decision4: 2 };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // Read the four selects. Values are 1/2/3; do NOT rebuild the UI here.
            var ok = true;
            for (var i = 1; i <= 4; i++) {
                var el = document.getElementById('decision' + i + 'Input');
                if (el) {
                    var v = parseInt(el.value, 10);
                    if (!Number.isFinite(v) || v < 1 || v > 3) { ok = false; }
                    decisions['decision' + i] = Number.isFinite(v) ? v : 0;
                }
            }
            if (!ok) {
                window.mySimulation.uiManager.showNotification(this._t('validation_warning'), 'warning');
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var avgGov = (d.decision1 + d.decision2 + d.decision3 + d.decision4) / 4;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var eventTriggered = avgGov < round.eventThreshold;
            var extractionRate = (4 - avgGov) / 3;
            var ecosystemMultiplier = ds.ecosystemHealth / 100;
            var regulatoryPenalty = Math.max(0, (45 - ds.regulatoryCompliance) / 150);
            var baseGrowth = 0.02 + extractionRate * 0.055 + ecosystemMultiplier * 0.035 - regulatoryPenalty * 0.07;
            if (eventTriggered && state.currentPeriod >= 3) { baseGrowth -= 0.03; }
            var revenueGrowth = ds.revenue * baseGrowth;
            var newRevenue = Math.round(ds.revenue + revenueGrowth);
            var ehDelta = (avgGov - 1.5) * 12;
            if (eventTriggered) { ehDelta -= 8; }
            if (ds.ecosystemHealth > 75 && avgGov >= 2.5) { ehDelta += 3; }
            var newEH = Math.max(0, Math.min(100, ds.ecosystemHealth + ehDelta));
            var rcDelta = (avgGov - 1.3) * 10;
            if (state.currentPeriod >= 3 && avgGov < 1.8) { rcDelta -= 12; }
            if (eventTriggered && state.currentPeriod === 3) { rcDelta -= 8; }
            var newRC = Math.max(0, Math.min(100, ds.regulatoryCompliance + rcDelta));
            var saDelta = (avgGov - 1.5) * 10;
            if (eventTriggered) { saDelta -= 5; }
            if (state.currentPeriod === 4 && avgGov < 1.8) { saDelta -= 10; }
            var newSA = Math.max(0, Math.min(100, ds.stakeholderAlignment + saDelta));
            var compDelta = Math.round((avgGov - 1.5) * 15);
            if (eventTriggered) { compDelta -= 12; }
            if (state.currentPeriod === 4 && eventTriggered) { compDelta -= 20; }
            var newComplementors = Math.max(100, ds.complementors + compDelta);
            var newActiveRate = Math.max(30, Math.min(95, ds.activeRate + (avgGov - 1.5) * 5));
            if (eventTriggered) { newActiveRate -= 3; }
            var activeComplementors = Math.round(newComplementors * newActiveRate / 100);
            var revenueScore = Math.min(100, Math.max(0, Math.round(newRevenue / 7)));
            var composite = Math.round(newEH * 0.30 + revenueScore * 0.25 + newRC * 0.25 + newSA * 0.20);

            ds.revenue = newRevenue;
            ds.ecosystemHealth = Math.round(newEH);
            ds.regulatoryCompliance = Math.round(newRC);
            ds.stakeholderAlignment = Math.round(newSA);
            ds.complementors = newComplementors;
            ds.activeRate = Math.round(newActiveRate);
            ds.activeComplementors = activeComplementors;
            ds.compositeScore = composite;
            ds.revenueHistory.push(newRevenue);
            ds.ecosystemHistory.push(Math.round(newEH));
            ds.regulatoryHistory.push(Math.round(newRC));
            ds.stakeholderHistory.push(Math.round(newSA));
            ds.compositeHistory.push(composite);

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                if (eventTriggered) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = this._L(state.currentPeriod).event;
                } else {
                    eventPanel.style.display = 'none';
                }
            }

            // Render next round synchronously (no setTimeout race). Preserve the event
            // panel visibility set just above.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, _keepEvent: true });

            return {
                period: state.currentPeriod,
                avgGovernance: Math.round(avgGov * 100) / 100,
                revenue: newRevenue,
                ecosystemHealth: Math.round(newEH),
                regulatoryCompliance: Math.round(newRC),
                stakeholderAlignment: Math.round(newSA),
                activeComplementors: activeComplementors,
                composite: composite,
                eventTriggered: eventTriggered
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.revenue', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('ecosystemDisplay', 'domainState.ecosystemHealth', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('regulatoryDisplay', 'domainState.regulatoryCompliance', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('stakeholderDisplay', 'domainState.stakeholderAlignment', function(v) { return Math.round(v) + '/100'; });
            // Bind the "Active Complementors" card to the ACTIVE count (not the total),
            // matching the label and the initial static value of 204.
            uiManager.bind('complementorsDisplay', 'domainState.activeComplementors', function(v) { return Math.round(v); });
            uiManager.bind('compositeDisplay', 'domainState.compositeScore', function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return { metricsChart: { type: 'line', data: { labels: [], datasets: [
